    fun resId(english: String): Int? = map[english] ?: builtInAppNameRes(english)
    fun get(context: Context, english: String): String = resId(english)?.let { context.getString(it) } ?: english
}

@Composable
fun ui(english: String): String = UiText.resId(english)?.let { stringResource(it) } ?: english

/** For non-composable code (toasts, notifications): ui(context, "Saved"). */
fun ui(context: Context, english: String): String = UiText.get(context, english)
